/// Why the parts `names` (sorted, distinct or not) may not make one
/// complex entity: a part repeated, a supertype part some part needs in
/// every edition missing, parts of unrelated hierarchies, two branches of a
/// ONEOF group, or an abstract part with none of its subtypes. `None` when
/// they may, or when a part is not one the model reads.
pub(crate) fn complex_violation(names: &[&str]) -> Option<&'static str> {
    if names.windows(2).any(|w| w[0] == w[1]) {
        return Some("complex entity repeats a part");
    }
    let mut rules: Vec<&(&str, bool, &[&str], &[&str])> = Vec::with_capacity(names.len());
    for n in names {
        let ix = READ_PART_RULES.binary_search_by(|r| r.0.cmp(n)).ok()?;
        rules.push(&READ_PART_RULES[ix]);
    }
    if rules
        .iter()
        .any(|r| r.2.iter().any(|a| names.binary_search(a).is_err()))
    {
        return Some("complex entity lacks a supertype part");
    }
    // Join each part with its supertypes present; more than one group left
    // means unrelated hierarchies.
    let mut group: Vec<usize> = (0..names.len()).collect();
    for (i, r) in rules.iter().enumerate() {
        for a in r.3 {
            if let Ok(j) = names.binary_search(a) {
                let (gi, gj) = (group[i], group[j]);
                if gi != gj {
                    for g in group.iter_mut() {
                        if *g == gj {
                            *g = gi;
                        }
                    }
                }
            }
        }
    }
    if group.iter().any(|&g| g != group[0]) {
        return Some("complex entity joins unrelated parts");
    }
    for (i, a) in names.iter().enumerate() {
        for b in &names[i + 1..] {
            if READ_ONEOF_CONFLICTS
                .binary_search_by(|(x, y)| (*x, *y).cmp(&(*a, *b)))
                .is_ok()
            {
                return Some("complex entity has parts of two ONEOF branches");
            }
        }
    }
    for (n, r) in names.iter().zip(&rules) {
        if r.1 && !rules.iter().any(|q| q.3.contains(n)) {
            return Some("complex entity has an abstract part without a subtype part");
        }
    }
    None
}

