/// The narrowings other parts may make of attribute `idx` of part `owner`.
pub fn complex_narrowings(owner: u16, idx: usize) -> &'static [ComplexNarrowing] {
    let start = COMPLEX_NARROWINGS.partition_point(|n| (n.owner, n.idx) < (owner, idx));
    let end = COMPLEX_NARROWINGS.partition_point(|n| (n.owner, n.idx) <= (owner, idx));
    &COMPLEX_NARROWINGS[start..end]
}

